text:
.popup-menu {
  position: absolute;
  display: block;
  z-index: 100;
  overflow: hidden;
  padding: 3px;
  color: var(--color-text-base);
  border: 1px solid var(--color-surface-border-intense);
  border-radius: 8px;
  background-color: var(--color-surface-subtle);
  box-shadow: 0 0 4px hsla(210, 4%, 10%, 0.2);

  &[variety="remainder"] .undo {
    display: none;
  }

  &:is([variety="include"], [variety="exclude"]) :is(.top, .bottom) {
    display: none;
  }

  &[variety="invisible"] {
    display: none;
  }
}

.popup-menuitem {
  font: menu;
  padding: 4px 10px;
  border-radius: 3px;

  &:is(:hover, :focus) {
    background-color: var(--selected-item-color);
    color: var(--selected-item-text-color);
  }

  &:focus {
    cursor: pointer;
  }
